"""Tests for merging into a shared limine.conf (D3)."""

from __future__ import annotations

from pathlib import Path
from unittest.mock import patch

import pytest

from arches_installer.core.limine_conf import (
    LimineMergeError,
    backup_limine_conf,
    check_merge,
    merge_problems,
    split_conf,
)

OLD_ID = "0688c1909f7144e5b1573566881d1324"
NEW_ID = "f" * 32

# The shape of p1's limine.conf (2026-10-27), shortened.
P1_CONF = f"""\
### Auto-generated by limine-entry-tool: https://gitlab.com/Zesko/limine-entry-tool

hash_mismatch_panic: no
timeout: 3
default_entry: Arch Linux/linux-cachyos


/+Arch Linux
### This OS entry is auto-generated by limine-entry-tool
comment: Arch Linux
comment: machine-id={OLD_ID} order-priority=50
  //linux-cachyos
  comment: kernel-id=linux-cachyos
  protocol: linux
  module_path: boot():/{OLD_ID}/linux-cachyos/initramfs#aa
  path: boot():/{OLD_ID}/linux-cachyos/vmlinuz#bb
  cmdline: root=UUID=64a8 rw rootflags=subvol=/@

     //Snapshots
     comment: 25 snapshots
     ///3375 │ 2026-10-27 10:00:01
     ////linux-cachyos
     protocol: linux
     path: boot():/{OLD_ID}/limine_history/vmlinuz#cc

/EFI fallback
  comment: Default EFI loader
  protocol: efi
  path: boot():/EFI/BOOT/BOOTX64.EFI

/Memtest86+
    protocol: efi
    path: boot():/memtest86+/memtest.efi
"""

OUR_ENTRY = f"""\
/+Arches Linux
comment: machine-id={NEW_ID} order-priority=50
  //linux-cachyos
  protocol: efi
  path: boot():/EFI/Linux/arches_linux-cachyos.efi#dd
  cmdline: root=UUID=new rw rootflags=subvol=/@

"""


def _with_ours(conf: str) -> str:
    head, _, rest = conf.partition("/+Arch Linux")
    return head + OUR_ENTRY + "/+Arch Linux" + rest


class TestSplit:
    def test_top_entries(self) -> None:
        header, entries = split_conf(P1_CONF)
        assert "timeout: 3" in header
        assert [e.title for e in entries] == [
            "Arch Linux",
            "EFI fallback",
            "Memtest86+",
        ]
        assert entries[0].machine_id == OLD_ID
        assert "///3375" in entries[0].text
        assert entries[1].machine_id == ""


class TestMergeProblems:
    def test_adding_our_entry_is_fine(self) -> None:
        assert merge_problems(P1_CONF, _with_ours(P1_CONF), NEW_ID) == []

    def test_changing_our_entry_is_fine(self) -> None:
        before = _with_ours(P1_CONF)
        after = before.replace(
            "arches_linux-cachyos.efi#dd", "arches_linux-cachyos.efi#ee"
        )
        assert merge_problems(before, after, NEW_ID) == []

    def test_reordering_is_fine(self) -> None:
        header, entries = split_conf(P1_CONF)
        after = header + "".join(e.text for e in reversed(entries))
        assert merge_problems(P1_CONF, after, NEW_ID) == []

    def test_changed_foreign_kernel_entry(self) -> None:
        after = _with_ours(P1_CONF).replace("vmlinuz#bb", "vmlinuz#xx")
        assert merge_problems(P1_CONF, after, NEW_ID) == [
            "entry 'Arch Linux' was changed or removed"
        ]

    def test_dropped_foreign_entry(self) -> None:
        header, entries = split_conf(P1_CONF)
        after = header + entries[0].text + entries[1].text
        assert merge_problems(P1_CONF, after, NEW_ID) == [
            "entry 'Memtest86+' was changed or removed"
        ]

    def test_changed_global_options(self) -> None:
        after = P1_CONF.replace("timeout: 3", "timeout: 5")
        assert merge_problems(P1_CONF, after, NEW_ID) == [
            "the global options (before the first entry) changed"
        ]

    def test_replaced_file(self) -> None:
        assert len(merge_problems(P1_CONF, OUR_ENTRY, NEW_ID)) >= 3


class TestBackupAndCheck:
    def test_backup_then_good_merge(self, tmp_path: Path) -> None:
        (tmp_path / "limine.conf").write_text(P1_CONF)
        backup = backup_limine_conf(tmp_path)
        assert backup is not None and backup.read_text() == P1_CONF
        assert backup.name.startswith("limine.conf.arches-")
        (tmp_path / "limine.conf").write_text(_with_ours(P1_CONF))
        check_merge(tmp_path, backup, NEW_ID)
        assert (tmp_path / "limine.conf").read_text() == _with_ours(P1_CONF)

    def test_bad_merge_restores_backup(self, tmp_path: Path) -> None:
        (tmp_path / "limine.conf").write_text(P1_CONF)
        backup = backup_limine_conf(tmp_path)
        (tmp_path / "limine.conf").write_text(OUR_ENTRY)
        with pytest.raises(LimineMergeError, match="backup was restored"):
            check_merge(tmp_path, backup, NEW_ID)
        assert (tmp_path / "limine.conf").read_text() == P1_CONF

    def test_no_conf_no_backup(self, tmp_path: Path) -> None:
        assert backup_limine_conf(tmp_path) is None


class TestSharedEspDefaults:
    def _write(self, tmp_path: Path, platform, esp_reused: bool) -> str:
        from arches_installer.core.bootloader import write_limine_defaults
        from arches_installer.core.disk import PartitionMap

        parts = PartitionMap(
            esp="/dev/nvme1n1p1",
            root="/dev/mapper/arches",
            root_filesystem="btrfs",
            root_subvolumes=["@"],
            esp_reused=esp_reused,
        )
        mod = "arches_installer.core.bootloader"
        with (
            patch(f"{mod}.MOUNT_ROOT", tmp_path),
            patch(f"{mod}.get_root_uuid", return_value="ROOTUUID"),
        ):
            write_limine_defaults(platform, parts.root, parts=parts)
        return (tmp_path / "etc" / "default" / "limine").read_text()

    def test_shared_esp_boots_ukis_under_own_name(
        self, tmp_path, x86_64_platform
    ) -> None:
        text = self._write(tmp_path, x86_64_platform, esp_reused=True)
        assert "ENABLE_UKI=yes\n" in text
        assert 'CUSTOM_UKI_NAME="arches"\n' in text
        assert 'TARGET_OS_NAME="Arches Linux"\n' in text
        # Enrolling the config hash waits for the attended Secure Boot step.
        assert "ENABLE_ENROLL_LIMINE_CONFIG=no\n" in text
        assert "root=UUID=ROOTUUID" in text

    def test_whole_disk_install_unchanged(self, tmp_path, x86_64_platform) -> None:
        text = self._write(tmp_path, x86_64_platform, esp_reused=False)
        assert "ENABLE_UKI" not in text
        assert "TARGET_OS_NAME" not in text


class TestPipelineMerge:
    def test_backup_before_pacstrap_check_after_bootloader(
        self, tmp_path, x86_64_platform, dev_workstation_template
    ) -> None:
        from unittest.mock import MagicMock

        from arches_installer.core.disk import PartitionMap
        from arches_installer.core.disk_layout import ResolvedDiskRoles
        from arches_installer.core.encryption import EncryptionSecrets
        from arches_installer.core.pipeline import InstallParams, run_install_pipeline
        from tests.core.test_existing import P1_LAYOUT

        from arches_installer.core.disk_layout import load_disk_layout

        backup = tmp_path / "limine.conf.arches-x.bak"
        backup.write_text(P1_CONF)
        (tmp_path / "etc").mkdir()
        (tmp_path / "etc" / "machine-id").write_text(NEW_ID + "\n")
        params = InstallParams(
            platform=x86_64_platform,
            template=dev_workstation_template,
            device="",
            hostname="h",
            username="u",
            password="p",
            disk_layout=load_disk_layout(P1_LAYOUT),
            resolved_disk_roles=ResolvedDiskRoles(),
            encryption=EncryptionSecrets("123456", lambda k: None),
        )
        parts = PartitionMap(
            esp="/dev/nvme1n1p1",
            root="/dev/mapper/arches",
            root_filesystem="btrfs",
            esp_reused=True,
        )
        order = MagicMock()
        order.backup_limine_conf.return_value = backup
        mod = "arches_installer.core.pipeline"
        with (
            patch("arches_installer.core.disk.MOUNT_ROOT", tmp_path),
            patch(f"{mod}.plan_existing_layout"),
            patch(f"{mod}.apply_existing_layout", return_value=parts),
            patch(f"{mod}.backup_limine_conf", order.backup_limine_conf),
            patch(f"{mod}.write_limine_defaults", order.write_limine_defaults),
            patch(f"{mod}.unmount_shared_esp", order.unmount_shared_esp),
            patch(f"{mod}.install_system", order.install_system),
            patch(f"{mod}.configure_target_storage"),
            patch(f"{mod}.prepare_secure_boot", order.prepare_secure_boot),
            patch(f"{mod}.install_bootloader", order.install_bootloader),
            patch(f"{mod}.check_merge", order.check_merge),
            patch(f"{mod}.setup_snapshots"),
            patch(f"{mod}.inject_firstboot_service"),
            patch(f"{mod}.write_disk_roles_state"),
            patch(f"{mod}._persist_install_log"),
        ):
            run_install_pipeline(params, log=lambda m: None)

        assert [c[0] for c in order.mock_calls] == [
            "backup_limine_conf",
            "write_limine_defaults",
            "unmount_shared_esp",
            "install_system",
            "prepare_secure_boot",
            "install_bootloader",
            "check_merge",
        ]
        assert order.check_merge.call_args[0][2] == NEW_ID
        kept = tmp_path / "var/lib/arches/limine.conf.before-install"
        assert kept.read_text() == P1_CONF


class TestPrePacstrapKeepsSharedEspDefaults:
    def test_existing_limine_defaults_survive(self, tmp_path) -> None:
        from arches_installer.core.install import _pre_pacstrap_setup

        etc = tmp_path / "etc"
        (etc / "default").mkdir(parents=True)
        (etc / "kernel").mkdir()
        (etc / "default" / "limine").write_text('TARGET_OS_NAME="Arches Linux"\n')
        (etc / "kernel" / "cmdline").write_text("root=UUID=new rw\n")
        mod = "arches_installer.core.install"
        with (
            patch(f"{mod}.MOUNT_ROOT", tmp_path),
            patch(f"{mod}._wait_for_keyring"),
            patch(f"{mod}._preseed_pacman_databases"),
            patch(f"{mod}._preseed_pacman_keyring"),
        ):
            _pre_pacstrap_setup()
        assert (
            etc / "default" / "limine"
        ).read_text() == 'TARGET_OS_NAME="Arches Linux"\n'
        assert (etc / "kernel" / "cmdline").read_text() == "root=UUID=new rw\n"

    def test_placeholders_on_a_fresh_target(self, tmp_path) -> None:
        from arches_installer.core.install import _pre_pacstrap_setup

        mod = "arches_installer.core.install"
        with (
            patch(f"{mod}.MOUNT_ROOT", tmp_path),
            patch(f"{mod}._wait_for_keyring"),
            patch(f"{mod}._preseed_pacman_databases"),
            patch(f"{mod}._preseed_pacman_keyring"),
        ):
            _pre_pacstrap_setup()
        assert (tmp_path / "etc/default/limine").read_text() == 'ESP_PATH="/boot"\n'
